// Processa respostas do Google Forms
const dados = $input.first().json;

// Mapeamento dos campos do formulário Google Forms
// Os nomes dos campos devem corresponder ao seu formulário
const anamnese = {
  // Dados pessoais
  nomePaciente: dados['Nome completo'] || dados.nome || '',
  dataNascimento: dados['Data de nascimento'] || dados.nascimento || '',
  cpf: dados['CPF'] || dados.cpf || '',
  telefone: dados['Telefone/WhatsApp'] || dados.telefone || '',
  email: dados['E-mail'] || dados.email || '',
  endereco: dados['Endereço completo'] || dados.endereco || '',
  profissao: dados['Profissão'] || dados.profissao || '',

  // Histórico médico
  motivoConsulta: dados['Qual o motivo da sua consulta?'] || '',
  temDorAtual: dados['Está com dor atualmente?'] || 'Não',
  localDor: dados['Se sim, onde é a dor?'] || '',
  ultimaConsultaDentista: dados['Quando foi sua última consulta com dentista?'] || '',

  // Saúde geral
  usaMedicamento: dados['Faz uso de algum medicamento?'] || 'Não',
  qualMedicamento: dados['Qual medicamento?'] || '',
  temAlergia: dados['Tem alergia a algum medicamento ou material?'] || 'Não',
  qualAlergia: dados['Qual alergia?'] || '',
  temDoencaSistemica: dados['Tem alguma doença sistêmica?'] || 'Não',
  qualDoencaSistemica: dados['Qual doença?'] || '',

  // Condições específicas
  hipertensao: dados['Hipertensão (pressão alta)?'] || 'Não',
  diabetes: dados['Diabetes?'] || 'Não',
  problemaCardiaco: dados['Problema cardíaco?'] || 'Não',
  gestante: dados['Está grávida? (para mulheres)'] || 'Não',
  fuma: dados['Fuma?'] || 'Não',
  tomaBebidaAlcoolica: dados['Consome bebida alcoólica?'] || 'Não',

  // Histórico odontológico
  jaFezCirurgiaOdonto: dados['Já fez alguma cirurgia odontológica?'] || 'Não',
  sangramentoAposProcedimento: dados['Já teve sangramento após procedimento dentário?'] || 'Não',
  temMedoTratamentoDental: dados['Tem medo ou ansiedade de tratamento dentário?'] || 'Não',
  observacoesAdicionais: dados['Observações adicionais'] || ''
};

return [{ json: anamnese }];

